import gsap from "gsap"
import { useGSAP } from "@gsap/react"

const BlurHome = () => {

    useGSAP( () => {
        gsap.to(".blurs", {
            x:990,
            duration: 1,
            repeat: 10,
        })
    },[])

    return(
        <div className="Maiblurs" >
            <div className="blurs" ></div>
        </div>
    )
}

export default BlurHome
